1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Scenario = {
14	  customer: { yearsWithMHPCO: number };
15	  steps: QuoteStep[];
16	};
17	
18	export type ScenarioResult = {
19	  results: unknown[];
20	};
21	
22	const PROCESSING_FEE = 5;
23	const FIRST_INSURANCE_SURCHARGE = 0.1;
24	
25	/** Premiums round up — in the MHPCO's favour. Float noise is discarded first. */
26	const roundUpToWholeG = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
27	
28	/** The item types the MHPCO will insure, and what each costs to cover. */
29	const BASE_PREMIUMS = {
30	  sword: 100,
31	  amulet: 60,
32	  staff: 80,
33	  potion: 40,
34	  rune: 25,
35	} as const satisfies Record<string, number>;
36	
37	type InsurableType = keyof typeof BASE_PREMIUMS;
38	
39	const basePremiumFor = (type: string): number => BASE_PREMIUMS[type as InsurableType];
40	
41	const quotePremium = (items: Item[]): number => {
42	  const policyBase = items.reduce((sum, item) => sum + basePremiumFor(item.type), 0);
43	  const withFirstInsurance = policyBase * (1 + FIRST_INSURANCE_SURCHARGE);
44	  const withProcessingFee = withFirstInsurance + PROCESSING_FEE;
45	  return roundUpToWholeG(withProcessingFee);
46	};
47	
48	export const runScenario = (scenario: Scenario): ScenarioResult => {
49	  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })) };
50	};
