/** The item types the MHPCO will insure, and what each costs to cover. */
const BASE_PREMIUMS: Record<string, number | undefined> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};

/** `undefined` for a type the MHPCO does not insure. Rejecting those is not yet specified by a test. */
const basePremiumFor = (type: string): number | undefined => BASE_PREMIUMS[type];
